import logging

from taf.fdsw.rc.schemas.FDSW19A.autoconnection_parameters_builder_19a import \
    Validator
from taf.fdsw.rc.schemas.FDSW20B.autoconnection_parameters_builder_20b import \
    AutoconnectionParametersBuilder20B

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoconnectionParametersBuilder21A(AutoconnectionParametersBuilder20B):
    def __init__(self, scenario, **kwargs):
        super(AutoconnectionParametersBuilder21A, self).__init__(**kwargs)

        if "inner_mplane_ip_version" in kwargs:
            inner_mplane_ip_version = kwargs["inner_mplane_ip_version"]

            self.management_plane_parameters.update(
                innerMplaneIpVersion=Validator.validate_param(
                    "inner_mplane_ip_version", inner_mplane_ip_version, (inner_mplane_ip_version in ["IPv4", "IPv6"])
                )
            )

        self.scenario = scenario

    def as_dict(self):
        attributes = super(AutoconnectionParametersBuilder21A, self).as_dict()
        attributes.update(scenario=Validator.validate_param(
            'scenario',
            self.scenario,
            (self.scenario in ['private network manual', 'private network with DHCP', 'public network'])))
        return attributes
